    pitchingApplicationStatusEnum = pgEnum("pitching_application_status", [
      "PENDING",
      "IN_REVIEW",
      "DATE_NEGOTIATION",
      "APPROVED",
      "REJECTED",
      "DISPUTE",
      "RESOLVED"
    ]);
    pitchingApplications = pgTable("pitching_applications", {
      id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
      applicationCode: varchar("application_code", { length: 12 }).unique(),
      // Unique code like APP-XXXXXX
      userId: varchar("user_id").notNull(),
      orgId: varchar("org_id").notNull(),
      trackId: varchar("track_id").notNull(),
      playlistId: integer("playlist_id").notNull(),
      packageId: integer("package_id").notNull(),
      curatorOrgId: varchar("curator_org_id").notNull(),
      spotifyLink: varchar("spotify_link"),
      instagramLink: varchar("instagram_link"),
      comment: text("comment"),
      photos: jsonb("photos").default([]),
      // Array of photo URLs/file IDs
      status: pitchingApplicationStatusEnum("status").default("PENDING"),
      curatorResponse: text("curator_response"),
      rejectionReason: varchar("rejection_reason"),
      // Reason code from PITCHING_REJECTION_REASONS
      paymentId: varchar("payment_id"),
      paymentStatus: varchar("payment_status").default("UNPAID"),
      // UNPAID, PENDING, PAID
      paidAt: timestamp("paid_at"),
      // When payment was completed
      paidAmount: integer("paid_amount"),
      paidCurrency: varchar("paid_currency"),
      spotifyTrackUrl: varchar("spotify_track_url"),
      // Found Spotify track URL for curator
      proposedPlacementDate: timestamp("proposed_placement_date"),
      // Date proposed by artist
      curatorProposedDate: timestamp("curator_proposed_date"),
      // Alternative date proposed by curator
      confirmedPlacementDate: timestamp("confirmed_placement_date"),
      // Final agreed placement date
      placementVerifiedAt: timestamp("placement_verified_at"),
      // When track was verified in playlist
      isPlacementVerified: boolean("is_placement_verified").default(false),
      // Whether track is confirmed in playlist
      disputeReason: text("dispute_reason"),
      // Reason for dispute
      disputeOpenedAt: timestamp("dispute_opened_at"),
      // When dispute was opened
      disputeResolvedAt: timestamp("dispute_resolved_at"),
      // When dispute was resolved
      disputeResolution: text("dispute_resolution"),
      // Admin resolution notes
      lastCuratorReminderAt: timestamp("last_curator_reminder_at"),
      // Track reminder timing
      createdAt: timestamp("created_at").defaultNow(),
      updatedAt: timestamp("updated_at").defaultNow(),
      reviewedAt: timestamp("reviewed_at")
    }, (table) => [
      index("idx_pitching_applications_user").on(table.userId),
      index("idx_pitching_applications_org").on(table.orgId),
      index("idx_pitching_applications_curator").on(table.curatorOrgId),
      index("idx_pitching_applications_playlist").on(table.playlistId),
      index("idx_pitching_applications_status").on(table.status),
      index("idx_pitching_applications_created").on(table.createdAt),
      index("idx_pitching_applications_code").on(table.applicationCode),
      index("idx_pitching_applications_placement_date").on(table.confirmedPlacementDate)
    ]);
