function formatDateUkrainian(date) {
  const months = [
    "\u0441\u0456\u0447\u043D\u044F",
    "\u043B\u044E\u0442\u043E\u0433\u043E",
    "\u0431\u0435\u0440\u0435\u0437\u043D\u044F",
    "\u043A\u0432\u0456\u0442\u043D\u044F",
    "\u0442\u0440\u0430\u0432\u043D\u044F",
    "\u0447\u0435\u0440\u0432\u043D\u044F",
    "\u043B\u0438\u043F\u043D\u044F",
    "\u0441\u0435\u0440\u043F\u043D\u044F",
    "\u0432\u0435\u0440\u0435\u0441\u043D\u044F",
    "\u0436\u043E\u0432\u0442\u043D\u044F",
    "\u043B\u0438\u0441\u0442\u043E\u043F\u0430\u0434\u0430",
    "\u0433\u0440\u0443\u0434\u043D\u044F"
  ];
  const day = date.getDate();
  const month = months[date.getMonth()];
  return `${day} ${month}`;
}
async function createReleaseCalendarEvent({
  releaseDate,
  artistName,
  releaseTitle,
  calendarEmail
}) {
  console.log(`\u{1F4C5} [Google Calendar] Starting event creation:`, {
    releaseDate: releaseDate.toISOString(),
    artistName,
    releaseTitle,
    calendarEmail
  });
  try {
    console.log(`\u{1F4C5} [Google Calendar] Getting calendar client...`);
    const calendar = await getUncachableGoogleCalendarClient();
    console.log(`\u2705 [Google Calendar] Calendar client obtained successfully`);
    const dateFormatted = formatDateUkrainian(releaseDate);
    const summary = `${artistName} \u2013 ${releaseTitle}`;
    const startDate = releaseDate.toISOString().split("T")[0];
    const endDate = new Date(releaseDate);
    endDate.setDate(endDate.getDate() + 1);
    const endDateStr = endDate.toISOString().split("T")[0];
    const event = {
      summary,
      description: `\u0420\u0435\u043B\u0456\u0437: ${releaseTitle}
\u0410\u0440\u0442\u0438\u0441\u0442: ${artistName}
\u0414\u0430\u0442\u0430 \u0432\u0438\u0445\u043E\u0434\u0443: ${dateFormatted}`,
      start: {
        date: startDate
      },
      end: {
        date: endDateStr
      },
      // Add reminder 1 day before
      reminders: {
        useDefault: false,
        overrides: [
          { method: "email", minutes: 24 * 60 },
          // 1 day before
          { method: "popup", minutes: 24 * 60 }
        ]
      }
    };
    console.log(`\u{1F4C5} [Google Calendar] Event object prepared:`, event);
    console.log(`\u{1F4C5} [Google Calendar] Inserting event into calendar: ${calendarEmail}`);
    const response = await calendar.events.insert({
      calendarId: calendarEmail,
      requestBody: event
    });
    console.log(`\u2705\u2705\u2705 Calendar event created successfully!`);
    console.log(`Event summary: ${summary}`);
    console.log(`Event link: ${response.data.htmlLink}`);
    console.log(`Event ID: ${response.data.id}`);
    return response.data;
  } catch (error) {
    console.error("\u274C\u274C\u274C Failed to create calendar event:", error);
    console.error("Error details:", {
      name: error.name,
      message: error.message,
      stack: error.stack
    });
    throw error;
  }
}

