      const merchantDomainName = "muzika.ua";
      const signString = [
        merchantAccount,
        merchantDomainName,
        orderReference,
        orderDate,
        amountUAH,
        currency,
        ...productName,
        ...productCount.map(String),
        ...productPrice.map(String)
      ].join(";");
      const merchantSignature = crypto4.createHmac("md5", secretKey).update(signString).digest("hex");
      const baseUrl = process.env.WAYFORPAY_SERVICE_URL || "https://muzika-dist.com";
