  app2.post("/api/admin/organizations/:orgId/create-member", isAuthenticated2, async (req, res) => {
    try {
      const userId = getUserId(req.user);
      if (!userId) {
        return res.status(401).json({ error: "User not authenticated" });
      }
      const user = await storage.getUser(userId);
      if (!user || !isPlatformAdmin(user)) {
        return res.status(403).json({ error: "Admin access required" });
      }
      const { orgId } = req.params;
      const { email, firstName, lastName, country, role } = req.body;
      if (!email) {
        return res.status(400).json({ error: "Email is required" });
      }
      if (!role || !["ADMIN", "MEMBER"].includes(role)) {
        return res.status(400).json({ error: "Invalid role. Must be ADMIN or MEMBER" });
      }
      const existingUser = await storage.getUserByEmail(email.toLowerCase());
      if (existingUser) {
        const isAlreadyMember = await storage.isOrgMember(existingUser.id, orgId);
        if (isAlreadyMember) {
          return res.status(409).json({ error: "This user is already a member of this organization" });
        }
        const member2 = await storage.addOrgMember(orgId, existingUser.id, role);
        return res.json({
          member: member2,
          message: "Existing user added to organization successfully"
        });
      }
      const tempPassword = crypto3.randomBytes(9).toString("base64").slice(0, 12);
      const passwordHash = await bcrypt3.hash(tempPassword, 10);
      const newUserId = await storage.createUser({
        email: email.toLowerCase(),
        firstName: firstName || "User",
        lastName: lastName || "",
        passwordHash,
        country: country || "UA",
        role: "ARTIST"
        // Default role for user record
      });
      const member = await storage.addOrgMember(orgId, newUserId, role);
      res.json({
        member,
        tempPassword,
        message: `User created successfully. Temporary password: ${tempPassword}`
      });
    } catch (error) {
      console.error("Error creating organization member:", error);
      if (error.code === "23505") {
        return res.status(409).json({ error: "A user with this email already exists" });
      }
      res.status(500).json({ error: "Failed to create organization member" });
    }
  });
